package org.apache.kafka.raft.internals;

import org.apache.kafka.raft.VoterSet;
import org.apache.kafka.server.common.KRaftVersion;

import java.util.Optional;

/**
 * KRaftVersionUpgrade is a sum types for coordinating the upgrade of the kraft version.
 *
 * {@code Voters} is used to stored in-memory the latest voter set. {@code Version} is used to
 * store in-memory the upgraded kraft version.
 *
 * This type makes it possible to upgrade the kraft version by only using compare-and-swap and
 * avoid blocking locks.
 */
public sealed interface KRaftVersionUpgrade {
    record Empty() implements KRaftVersionUpgrade {
    }

    record Version(KRaftVersion kraftVersion) implements KRaftVersionUpgrade {
    }

    record Voters(VoterSet voters) implements KRaftVersionUpgrade {
    }

    default Optional<Voters> toVoters() {
        if (this instanceof Voters v) {
            return Optional.of(v);
        } else {
            return Optional.empty();
        }
    }

    default Optional<Version> toVersion() {
        if (this instanceof Version v) {
            return Optional.of(v);
        } else {
            return Optional.empty();
        }
    }

    KRaftVersionUpgrade EMPTY = new Empty();

    static KRaftVersionUpgrade empty() {
        return EMPTY;
    }

}

